/** コンパクト表記（1m/9p/1s/東 等）。Unicode 牌を優先し、フォント欠如時のみ補助表示に使う */
function tileCompactLabel(idx) {
  if (idx >= 0 && idx <= 8) return (idx + 1) + 'm';
  if (idx >= 9 && idx <= 17) return (idx - 8) + 'p';
  if (idx >= 18 && idx <= 26) return (idx - 17) + 's';
  const honor = ['東', '南', '西', '北', '白', '發', '中'];
  if (idx >= 27 && idx <= 33) return honor[idx - 27];
  return '?';
}

let _mahjongGlyphNarrow = null;
/**
 * 麻雀牌ブロックのグリフが「極端に狭い＝欠グリフの置換や不適切なフォールバック」の疑いがあるかを一度だけ検査する。
 * true のときだけ .tile--with-fallback を付け、tileCompactLabel を重ねる（主表示は常に codepoint のまま）。
 */
function mahjongGlyphLikelyUnsupported() {
  if (_mahjongGlyphNarrow !== null) return _mahjongGlyphNarrow;
  const test = document.createElement('span');
  test.setAttribute('aria-hidden', 'true');
  test.style.cssText = [
    'position:fixed',
    'left:-9999px',
    'top:0',
    'visibility:hidden',
    'pointer-events:none',
    'display:inline-flex',
    'font-size:36px',
    'line-height:1.05',
    'font-family:"Segoe UI Emoji","Apple Color Emoji","Noto Sans Symbols 2","Noto Sans Symbols","Segoe UI Symbol","Twemoji Mozilla","Noto Color Emoji",sans-serif',
    'font-variant-emoji:emoji'
  ].join(';');
  test.textContent = String.fromCodePoint(0x1f007);
  document.body.appendChild(test);
  const w = test.getBoundingClientRect().width;
  document.body.removeChild(test);
  _mahjongGlyphNarrow = w < 24;
  return _mahjongGlyphNarrow;
}

function populateTileElement(el, tileIndex) {
  el.textContent = '';
  const uc = document.createElement('span');
  uc.className = 'tile-uc';
  uc.textContent = tileUnicode(tileIndex);
  const fb = document.createElement('span');
  fb.className = 'tile-fallback';
  fb.setAttribute('aria-hidden', 'true');
  fb.textContent = tileCompactLabel(tileIndex);
  el.appendChild(uc);
  el.appendChild(fb);
  if (mahjongGlyphLikelyUnsupported()) el.classList.add('tile--with-fallback');
}

